using System;
using System.Reflection;
using LastRail.Presentation.Audio;
using LastRail.Presentation.Battle;
using NUnit.Framework;
using UnityEngine;

public sealed class ReinaCinematicAudioPlaybackTests {
 const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static object Call(object owner,string name,params object[] args){try{return owner.GetType().GetMethod(name,Hidden).Invoke(owner,args);}catch(TargetInvocationException error){throw error.InnerException;}}
 static Type NativeType(){var type=typeof(LastRailAudioCuePlayer).Assembly.GetType("LastRail.Presentation.Audio.ReinaCinematicAudioPlayback");Assert.NotNull(type,"Missing full baked Reina native audio owner.");return type;}
 sealed class Fixture:IDisposable {
  internal readonly GameObject Root;internal readonly AudioSource Source;internal readonly AudioClip Clip;internal readonly object Playback;
  internal IDisposable Lease;internal int Ended,Skipped,Errors;internal double OutputSeconds;
  internal Fixture(){Root=new GameObject("TEST_ONLY_Reina_audio_source");Source=Root.AddComponent<AudioSource>();Clip=AudioClip.Create("TEST_ONLY_8.95_seconds_no_bgm",8950,1,1000,false);Playback=Activator.CreateInstance(NativeType(),new object[]{Source,Clip,1f});}
  internal void Begin(){Lease=(IDisposable)Call(Playback,"Begin",(Action)(()=>Ended++),(Action)(()=>Skipped++),(Action<Exception>)(e=>Errors++));}
  // Explicit synthetic device observation; no audible output or actual device timing is claimed.
  internal void Observe(int sample,bool playing,double dsp){OutputSeconds=dsp;Call(Playback,"ObserveSource",sample,playing,dsp);}
  internal void Skip()=>Call(Playback,"SkipAt",OutputSeconds);
  internal void Pause(bool paused)=>Call(Playback,"SetPausedAt",paused,OutputSeconds);
  internal long Position=>(long)Playback.GetType().GetProperty("PositionTicks").GetValue(Playback);
  public void Dispose(){if(Playback is IDisposable d)d.Dispose();UnityEngine.Object.DestroyImmediate(Root);UnityEngine.Object.DestroyImmediate(Clip);}
 }
 [Test] public void FullStemStartsAtBeginAndHasNoDelayedSecondDepthPlayback(){using var f=new Fixture();f.Begin();Assert.AreSame(f.Clip,f.Source.clip);Assert.AreEqual(1f,f.Source.pitch);Assert.IsFalse(f.Source.loop);Assert.AreEqual(1f,f.Source.volume);f.Observe(2600,true,2.6);Assert.AreEqual(2600*TimeSpan.TicksPerMillisecond,f.Position);Assert.AreSame(f.Clip,f.Source.clip);Assert.AreEqual(0,f.Ended);}
 [Test] public void FrameOvershootCannotStopPlayingFullClipAtNominalEnd(){using var f=new Fixture();f.Begin();f.Observe(0,true,0);f.Observe(8900,true,12);Assert.AreEqual(0,f.Ended);Assert.AreSame(f.Clip,f.Source.clip);f.Observe(0,false,12.1);Assert.AreEqual(1,f.Ended);Assert.IsNull(f.Source.clip);f.Observe(0,false,13);Assert.AreEqual(1,f.Ended);}
 [Test] public void PausePreservesOriginalSamplePositionWithoutBeginReplay(){using var f=new Fixture();f.Begin();f.Observe(3000,true,3);f.Pause(true);f.Observe(3000,false,23);Assert.AreEqual(3000*TimeSpan.TicksPerMillisecond,f.Position);Assert.AreEqual(0,f.Ended);f.Pause(false);f.Observe(3500,true,23.5);Assert.AreEqual(3500*TimeSpan.TicksPerMillisecond,f.Position);Assert.AreSame(f.Clip,f.Source.clip);Assert.AreEqual(1f,f.Source.pitch);}
 [Test] public void SkipBeforeDepthStillFadesAlreadyPlayingVoiceAndReleasesSessionImmediately(){using var f=new Fixture();f.Begin();f.Observe(1000,true,1);f.Skip();f.Lease.Dispose();Assert.AreEqual(1,f.Skipped);Assert.AreSame(f.Clip,f.Source.clip);f.Observe(1040,true,1.04);Assert.That(f.Source.volume,Is.EqualTo(.5f).Within(.0001));f.Observe(1080,true,1.08);Assert.IsNull(f.Source.clip);Assert.AreEqual(0,f.Ended);}
 [Test] public void LatestEffectsSettingMultipliesOnlyOwnFadeAndPitchNeverChanges(){using var f=new Fixture();f.Begin();f.Observe(1000,true,1);f.Skip();Call(f.Playback,"SetEffectsGain",.4f);f.Observe(1040,true,1.04);Assert.That(f.Source.volume,Is.EqualTo(.2f).Within(.0001));Assert.AreEqual(1f,f.Source.pitch);}
 [Test] public void OwnerDisposeStopsSkippedTailImmediately(){using var f=new Fixture();f.Begin();f.Observe(1000,true,1);f.Skip();((IDisposable)f.Playback).Dispose();Assert.IsNull(f.Source.clip);f.Observe(1040,true,1.04);Assert.IsNull(f.Source.clip);Assert.AreEqual(1,f.Skipped);}
 [Test] public void WrongDurationCannotBeSubstitutedForTheSuppliedFullStem(){var root=new GameObject("invalidclip");var clip=AudioClip.Create("TEST_ONLY_wrong",1000,1,1000,false);try{var error=Assert.Throws<TargetInvocationException>(()=>Activator.CreateInstance(NativeType(),new object[]{root.AddComponent<AudioSource>(),clip,1f}));Assert.IsInstanceOf<ArgumentException>(error.InnerException);}finally{UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(clip);}}
 [Test] public void FullVoiceFactoryBeginsAtZeroButExistingDepthFactoryStillWaits(){int started=0;var factory=typeof(ReinaCinematicPlayback).GetMethod("ForFullVoiceFx",BindingFlags.Static|BindingFlags.Public);Assert.NotNull(factory,"Missing explicit full-stem playback mode.");using var full=(ReinaCinematicPlayback)factory.Invoke(null,new object[]{(Action)(()=>started++),(Action<bool>)(_=>{}),(Action<float>)(_=>{}),(Action)(()=>{})});full.Begin(()=>{},()=>{},e=>Assert.Fail(e.ToString()));Assert.AreEqual(1,started);using var old=new ReinaCinematicPlayback(()=>started++,_=>{},_=>{},()=>{});old.Begin(()=>{},()=>{},e=>Assert.Fail(e.ToString()));Assert.AreEqual(1,started);}
 [Test] public void ExistingAudioOwnerAppliesMenuAndApplicationHoldWithoutDiscardingCinematic(){var root=new GameObject("TEST_ONLY_existing_audio_owner");var clip=AudioClip.Create("TEST_ONLY_full",8950,1,1000,false);try{var player=root.AddComponent<LastRailAudioCuePlayer>();var child=new GameObject("owned-cinematic");child.transform.SetParent(root.transform);var source=child.AddComponent<AudioSource>();Call(player,"ConfigureReinaCinematicSource",source);player.ConfigureCombatSources(Array.Empty<AudioSource>(),null);player.BeginCombatScope(this,1);player.ApplyMixSettings(.7f,.6f);int ends=0;var playback=Call(player,"BeginReinaCinematic",clip,(Action)(()=>ends++),(Action)(()=>{}),(Action<Exception>)(e=>Assert.Fail(e.ToString())));Assert.AreSame(clip,source.clip);Assert.AreEqual(.6f,source.volume);using(var hold=player.AcquireAudioHold()){Assert.AreSame(clip,source.clip);Call(player,"OnApplicationPause",true);Call(player,"OnApplicationPause",false);Assert.AreEqual(0,ends);}Assert.AreSame(clip,source.clip);player.EndCombatScope();Assert.IsNull(source.clip);Assert.AreEqual(0,ends);Assert.NotNull(playback);}finally{UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(clip);}}
 [Test] public void ExistingOwnerRejectsSharedVoiceAndConcurrentCinematics(){var root=new GameObject("TEST_ONLY_voice_ownership");var clip=AudioClip.Create("TEST_ONLY_full",8950,1,1000,false);try{var player=root.AddComponent<LastRailAudioCuePlayer>();var source=root.AddComponent<AudioSource>();player.ConfigureCombatSources(new[]{source},null);Assert.Throws<ArgumentException>(()=>Call(player,"ConfigureReinaCinematicSource",source));player.ConfigureCombatSources(Array.Empty<AudioSource>(),null);Call(player,"ConfigureReinaCinematicSource",source);player.BeginCombatScope(this,1);Call(player,"BeginReinaCinematic",clip,(Action)(()=>{}),(Action)(()=>{}),(Action<Exception>)(_=>{}));Assert.Throws<InvalidOperationException>(()=>Call(player,"BeginReinaCinematic",clip,(Action)(()=>{}),(Action)(()=>{}),(Action<Exception>)(_=>{})));}finally{UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(clip);}}
 [Test] public void FirstStoppedDeviceObservationFailsInsteadOfKeepingPresentationHoldForever(){using var f=new Fixture();f.Begin();f.Observe(0,false,0);Assert.AreEqual(1,f.Errors);Assert.AreEqual(0,f.Ended);Assert.IsNull(f.Source.clip);f.Observe(0,false,20);Assert.AreEqual(1,f.Errors);Assert.AreEqual(0,f.Ended);}
 [Test] public void UnexpectedStopBeforeFullDurationCannotBecomeSuccessfulEndLater(){using var f=new Fixture();f.Begin();f.Observe(1000,true,1);f.Observe(0,false,1.1);Assert.AreEqual(1,f.Errors);Assert.AreEqual(0,f.Ended);Assert.IsNull(f.Source.clip);f.Observe(0,false,10);Assert.AreEqual(0,f.Ended);Assert.AreEqual(1,f.Errors);}
 [Test] public void SkipBetweenObservationsStartsItsOwnEightyMillisecondsAtTheCommandBoundary(){using var f=new Fixture();f.Begin();f.Observe(1000,true,1);Call(f.Playback,"SkipAt",1.05);f.Observe(1060,true,1.06);Assert.That(f.Source.volume,Is.EqualTo(.875f).Within(.0001));f.Observe(1120,true,1.12);Assert.IsNotNull(f.Source.clip);f.Observe(1130,true,1.13);Assert.IsNull(f.Source.clip);}
 [Test] public void PauseBoundarySettlesAudibleFadeTimeBeforeFreezingItsRemainder(){using var f=new Fixture();f.Begin();f.Observe(1000,true,1);f.Skip();f.Observe(1040,true,1.04);Call(f.Playback,"SetPausedAt",true,1.06);Assert.That(f.Source.volume,Is.EqualTo(.25f).Within(.0001));f.Observe(1060,false,1.06);Call(f.Playback,"SetPausedAt",false,1.06);f.Observe(1080,true,1.08);Assert.IsNull(f.Source.clip);Assert.AreEqual(0,f.Errors);}
}
